const $=id=>document.getElementById(id),params=new URLSearchParams(location.search),game=['gomoku','puzzle','chess','draw','cards','pool'].includes(params.get('game'))?params.get('game'):'four',title=game==='four'?'四子连珠':game==='gomoku'?'五子棋':game==='chess'?'国际象棋':game==='draw'?'你画我猜':game==='cards'?'欢乐纸牌':game==='pool'?'欢乐台球':'趣味拼图';
let board=start(game),room=null,csrf=null,pending=false,computer=false,local=true,me=null,poll=null,generation=0,last=-1,rematchPending=false,puzzleSelection=null;
$('title').textContent=title;$('game-name').textContent=title;document.title=title+' · JoyFlock';$('rules').textContent=game==='four'?'轮流选择一列落子，棋子落到该列最下方的空位。横、竖或斜向连成4颗即获胜。':'双方轮流落子，黑棋先行。横、竖或斜向连成5颗及以上获胜；当前为无禁手的自由五子棋。';$('board').classList.toggle('chess',game==='chess');$('promotion-setting').hidden=game!=='chess';if(game==='chess')$('rules').textContent='白棋先行。点击自己的棋子，再点击目标格。支持王车易位、吃过路兵及升变；将死获胜，逼和、重复局面、50回合及子力不足判和。电脑为基础难度。';$('board').classList.toggle('gomoku',game==='gomoku');$('board').classList.toggle('puzzle',game==='puzzle');if(game==='puzzle'){$('score-note').textContent='登录账号的联机合作成果自动保存，每位参与者各+3分；单机和游客对局不累计。';$('rules').textContent='交换两块拼图，还原完整的飞行棋画面。点击两块图片交换位置，也可以拖动交换。联机时与好友轮流协作；完成后两人各+3分。';$('computer').textContent='单机 · 电脑协作';$('local').textContent='单机 · 双人协作';}
async function request(path,body){const response=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{...(body===undefined?{}:{'content-type':'application/json'}),...(csrf?{[csrf.headerName]:csrf.token}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});if(!response.ok){const error=Error('请求失败 ('+response.status+')');error.status=response.status;throw error;}const text=await response.text();return text?JSON.parse(text):null;}
async function init(){if(!csrf){csrf=await request('/api/csrf');await request('/api/session/guest',{});}me=await request('/api/me');$('profile').textContent=(me.account?.displayName||'游客')+(me.appearance?.annualMember?' · YEAR VIP':me.appearance?.member?' · VIP':'');$('profile').classList.toggle('vip',!!me.appearance?.member);$('account-open').textContent=me.account?me.account.displayName:'登录 / 注册';await refreshStats();refreshLeaderboard();}
async function refreshLeaderboard(){try{const rows=await request('/api/table/leaderboards/'+game);$('leaderboard').replaceChildren(...rows.map(row=>{const li=document.createElement('li'),name=document.createElement('span'),score=document.createElement('b');name.textContent=row.name+(row.annualMember?' · YEAR VIP':row.member?' · VIP':'');score.textContent=row.points+'分 / '+row.games+'局';li.append(name,score);return li;}));if(!rows.length)$('leaderboard').textContent='暂无已记录的联机成绩。';}catch{}}
async function refreshStats(){if(!me?.account){$('stats').textContent='登录后可查看本游戏的累计积分。';return;}try{const stats=await request('/api/table/stats/'+game);$('stats').textContent='本游戏累计：'+stats.points+' 积分 · '+stats.completedGames+' 局';}catch{}}
const names=()=>room?.names||['你',computer?'电脑':'好友'];
function render(){const waiting=room?.phase==='WAITING',can=!pending&&!board.over&&!waiting&&(!room||room.phase==='PLAYING'&&room.you+1===board.turn)&&!(local&&computer&&board.turn===2);$('mode').textContent=room?'服务端联机':game==='puzzle'?(computer?'单机 · 电脑协作':'单机 · 双人协作'):computer?'单机 · 电脑对战':'单机 · 双人同屏';$('status').textContent=room?.phase==='SUSPENDED'?'对局已在另一个窗口恢复':room?.phase==='CLOSED'?'房间已关闭，请重新创建。':waiting?(room.deadline>0?'正在匹配，'+Math.max(0,Math.ceil((room.deadline-room.serverNow)/1000))+'秒后电脑补位':'等待好友加入并准备'):board.over?(board.winner?(game==='puzzle'?'拼图完成，合作愉快！':names()[board.winner-1]+' 获胜！'):(game==='chess'?'本局和棋。':'棋盘已满，平局。')):names()[board.turn-1]+' 的回合'+(room?' · 超时电脑代走':'');if(game==='pool')renderPool($('board'),board,can);else if(game==='cards')renderCards($('board'),board,room?room.you+1:computer?1:board.turn,can);else if(game==='draw'){drawSketch($('board'),board,{you:room?room.you+1:board.turn,network:!!room,practice:computer&&!room,send:sketchAction,next:()=>{board=sketchNext(board);if(computer&&!board.over)practiceDrawing();$('board')._passed=false;render();}});}else $('board').innerHTML=board.cells.map((v,i)=>game==='chess'?`<button class="cell chess-square ${(Math.floor(i/8)+i%8)%2?'dark':'light'} ${v>6?'black-piece':'white-piece'} ${puzzleSelection===i?'chosen':''}" data-position="${i}" aria-label="${String.fromCharCode(97+i%8)}${8-Math.floor(i/8)} ${v?['','白兵','白马','白象','白车','白后','白王','黑兵','黑马','黑象','黑车','黑后','黑王'][v]:'空格'}" ${!can?'disabled':''}>${v?[...'♙♘♗♖♕♔♟♞♝♜♛♚'][v-1]:''}</button>`:game==='puzzle'?`<button class="cell puzzle-tile ${puzzleSelection===i?'chosen':''}" style="background-position:${((v-1)%4)*100/3}% ${Math.floor((v-1)/4)*100/3}%" data-position="${i}" draggable="true" aria-label="第${i+1}个位置，图片${v}" ${!can?'disabled':''}><small>${v}</small></button>`:`<button class="cell ${i===last?'last':''}" data-value="${v}" data-position="${game==='four'?i%7:i}" aria-label="${game==='four'?'第'+(i%7+1)+'列':'第'+(Math.floor(i/15)+1)+'行第'+(i%15+1)+'列'}，${v?'已有棋子':'空位'}" ${!can?'disabled':''}></button>`).join('');$('seats').replaceChildren(...[0,1].map(i=>{const el=document.createElement('div');el.className='seat'+(board.turn===i+1&&!board.over?' active':'');const profile=room?.profiles?.[i];const name=document.createElement('span');name.textContent=(names()[i]||'等待加入')+(room?.bots[i]?' · BOT':'');el.append(name);if(profile?.avatarUrl&&/^\/api\/avatars\//.test(profile.avatarUrl)){const img=document.createElement('img');img.src=profile.avatarUrl;img.alt='';img.className='seat-avatar';el.prepend(img);}if(profile?.member){el.classList.add('member');const badge=document.createElement('small');badge.textContent=profile.annualMember?'YEAR VIP':'VIP';el.append(badge);}return el;}));$('room-tools').hidden=!room;$('ready').hidden=!room||room.origin!=='FRIENDS'||room.phase!=='WAITING'||room.deadline>0;$('share').hidden=room?.origin!=='FRIENDS'||room?.phase!=='WAITING';$('room-status').textContent=room?'房间 '+room.id:'';$('again').hidden=!board.over;}
function apply(value){if(room&&value.id!==room.id)rematchPending=false;if(value.game!==game)throw Error('游戏类型不匹配');if(!room||value.version!==room.version)puzzleSelection=null;room=value;board=value.board;local=false;render();if(board.over){refreshStats();refreshLeaderboard();if(!rematchPending)clearInterval(poll);$('stats').textContent=me?.account?'已完成的联机结果由服务器保存；本游戏独立计分。':'游客对局不累计积分。';}}
function schedulePoll(){clearInterval(poll);let reading=false;const token=generation;poll=setInterval(async()=>{if(reading||!room||pending||document.hidden)return;reading=true;try{const next=await request('/api/table/rooms/'+room.id);if(token===generation){apply(next);$('message').textContent='';}}catch(error){if([403,404].includes(error.status)){clearInterval(poll);if(room)room.phase=error.status===403?'SUSPENDED':'CLOSED';$('message').textContent=error.status===403?'当前对局已由其他窗口接管，或席位不可用。':'房间已不可用，请重新匹配。';render();}else $('message').textContent='连接中断，正在重新连接…';}finally{reading=false;}},1000);}
async function enter(mode,code){if(pending)return;pending=true;const token=++generation;clearInterval(poll);try{await init();const value=code?await request('/api/table/rooms/'+code+'/join',{}):await request('/api/table/rooms',{game,mode});if(token!==generation)return;apply(value);const url=new URL(location.href);url.searchParams.set('room',room.id);history.replaceState(null,'',url);schedulePoll();$('message').textContent='';}catch(e){$('message').textContent=e.status===409?'房间已开始、已满，或同一账号已在房间中。':'未能进入，请重试。';}finally{pending=false;render();}}
function localStart(withBot){generation++;clearInterval(poll);room=null;local=true;computer=withBot;board=start(game);if(game==='pool'){$('board')._animationToken=($('board')._animationToken||0)+1;$('board')._animating=false;$('board')._lastMove=0;}if(game==='draw'){$('board')._passed=false;computer&&practiceDrawing();}puzzleSelection=null;last=-1,rematchPending=false;pending=false;const url=new URL(location.href);url.searchParams.delete('room');history.replaceState(null,'',url);$('message').textContent='单机结果不上传。';render();}
$('board').addEventListener('click',async event=>{const button=event.target.closest('[data-position]');if(game==='draw'||!button||pending||board.over||game==='pool'&&$('board')._animating)return;let position=Number(button.dataset.position);if(game==='chess'){const own=board.cells[position]&&(board.cells[position]<=6?1:2)===board.turn;if(puzzleSelection===null||own){if(!own)return;puzzleSelection=position;render();return;}let code=puzzleSelection*64+position;const pawn=board.cells[puzzleSelection]===1||board.cells[puzzleSelection]===7;if(pawn&&(Math.floor(position/8)===0||Math.floor(position/8)===7))code+=4096*Number($('promotion').value);if(!legal(board).includes(code)){$('message').textContent='这步不合法，请选择其他目标。';return;}position=code;puzzleSelection=null;}if(game==='puzzle'){if(puzzleSelection===null){puzzleSelection=position;render();return;}if(puzzleSelection===position){puzzleSelection=null;render();return;}position=puzzleSelection*16+position;puzzleSelection=null;}const token=generation;pending=true;render();try{if(room){const next=await request('/api/table/rooms/'+room.id+'/move',{position,version:room.version,commandId:crypto.randomUUID()});if(token!==generation)return;apply(next);}else{board=move(board,board.turn,position);render();if(computer&&!board.over){await new Promise(r=>setTimeout(r,game==='pool'?2000:450));if(token!==generation)return;board=move(board,board.turn,bot(board));}}}catch(e){$('message').textContent='此处不能落子，或状态已变化，请重试。';}finally{if(token===generation){pending=false;render();}}});
$('computer').onclick=()=>localStart(true);$('local').onclick=()=>localStart(false);$('quick').onclick=()=>enter('QUICK');$('friends').onclick=()=>enter('FRIENDS');$('join').onsubmit=event=>{event.preventDefault();let code=$('room-code').value.trim();try{if(code.includes('://'))code=new URL(code).searchParams.get('room');if(!/^[0-9a-f-]{36}$/i.test(code||''))throw Error();enter('FRIENDS',code);}catch{$('message').textContent='请填写有效的房间码或邀请链接。';}};
$('share').onclick=async()=>{const url=new URL(location.href);url.searchParams.set('room',room.id);try{await navigator.clipboard.writeText(url.href);$('message').textContent='邀请链接已复制，发给朋友即可。';}catch{$('room-code').value=url.href;$('message').textContent='请复制输入框中的邀请链接。';}};
$('leave').onclick=async()=>{if(pending)return;pending=true;try{await request('/api/table/rooms/'+room.id+'/leave',{});localStart(false);}catch{$('message').textContent='退出未成功，请重试。';}finally{pending=false;render();}};
$('again').onclick=async()=>{if(!room){localStart(computer);return;}if(pending)return;pending=true;try{rematchPending=true;apply(await request('/api/table/rooms/'+room.id+'/rematch',{}));schedulePoll();$('message').textContent=room.phase==='OVER'?'等待好友确认再来一局。':'';}catch{$('message').textContent='重新开始失败，请重试。';}finally{pending=false;render();}};
$('account-open').onclick=()=>{const old=$('account-summary');if(old)old.remove();$('auth-form').hidden=!!me?.account;if(me?.account){const section=document.createElement('section');section.id='account-summary';section.innerHTML='<h2></h2><p></p><button type="button" id="signout">退出登录</button><button type="button" id="summary-close">关闭</button>';section.querySelector('h2').textContent=me.account.displayName;section.querySelector('p').textContent=(me.appearance?.annualMember?'YEAR VIP':me.appearance?.member?'VIP':'普通账号')+' · '+$('stats').textContent;$('auth').append(section);$('signout').onclick=async()=>{await request('/api/auth/logout',{});await init();$('auth').close();};$('summary-close').onclick=()=>$('auth').close();}$('auth').showModal();};$('auth-close').onclick=()=>$('auth').close();$('auth-form').onsubmit=async event=>{event.preventDefault();const form=event.target,values=Object.fromEntries(new FormData(form)),action=event.submitter.value;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)){$('auth-error').textContent='请输入完整的邮箱地址。';return;}if(action==='register'&&values.password!==values.confirmation){$('auth-error').textContent='两次输入的密码不一致。';return;}if(action==='register'&&!values.displayName.trim()){$('auth-error').textContent='注册请填写昵称。';return;}for(const b of form.querySelectorAll('button'))b.disabled=true;try{await init();await request('/api/auth/'+action,values);await init();form.reset();$('auth').close();}catch(e){$('auth-error').textContent=e.status===409?'邮箱已被使用。':e.status===401?'邮箱或密码不正确。':'未成功，请检查邮箱和密码（至少8位）后重试。';}finally{for(const b of form.querySelectorAll('button'))b.disabled=false;}};
render();init().then(()=>{if(params.get('room'))enter('FRIENDS',params.get('room'));}).catch(()=>{$('message').textContent='联机服务暂不可用，仍可单机游玩。';});

import {bindPortalControls} from '../portal-controls.js?v=20261104-home';
bindPortalControls();
$('home-link').onclick=async event=>{event.preventDefault();if(room&&room.phase!=='OVER'){if(!confirm('返回游戏首页？当前席位将由电脑托管。'))return;try{await request('/api/table/rooms/'+room.id+'/leave',{});}catch{$('message').textContent='退出未成功，请重试。';return;}}localStart(false);};
let draggedTile=null;$('board').addEventListener('dragstart',event=>{const tile=event.target.closest('[data-position]');if(game!=='puzzle'||!tile||tile.disabled){event.preventDefault();return;}draggedTile=Number(tile.dataset.position);});$('board').addEventListener('dragover',event=>{if(game==='puzzle')event.preventDefault();});$('board').addEventListener('drop',event=>{event.preventDefault();const tile=event.target.closest('[data-position]');if(tile&&draggedTile!==null&&!tile.disabled){puzzleSelection=draggedTile;tile.click();}draggedTile=null;});

$('ready').onclick=async()=>{if(!room||pending)return;pending=true;try{apply(await request('/api/table/rooms/'+room.id+'/ready',{}));$('message').textContent='已准备，等待好友。';}catch{$('message').textContent='准备失败，请重试。';}finally{pending=false;render();}};

async function sketchAction(action,text,points){if(pending||board.over)return;pending=true;try{if(room)apply(await request('/api/table/rooms/'+room.id+'/sketch',{commandId:crypto.randomUUID(),version:room.version,action,text,points}));else{if(action==='stroke')board={...board,history:[...board.history,points.join(',')]};if(action==='clear')board={...board,history:[]};if(action==='guess'&&text.trim()===board.fen){board=sketchNext(board,true);$('board')._passed=false;if(computer&&!board.over)practiceDrawing();}}}catch{$('message').textContent='猜题请间隔1秒，每题最多6次；或当前状态已变化，请重试。';}finally{pending=false;render();}}
function practiceDrawing(){const n=Math.floor(Math.random()*3);board.fen=['三角形','正方形','圆形'][n];const points=n===0?[500,180,220,780,780,780,500,180]:n===1?[250,250,750,250,750,750,250,750,250,250]:Array.from({length:49},(_,i)=>[Math.round(500+280*Math.cos(i*Math.PI/24)),Math.round(500+280*Math.sin(i*Math.PI/24))]).flat();board.history=[points.join(',')];}
if(game==='draw'){$('board').classList.add('sketch');$('rules').textContent='两人轮流画画与猜词，共6题。猜对者得2题分，画画者得1题分；每题最多猜6次，猜题间隔1秒；最终按题分排名结算。单机电脑出图为几何图形练习，不模拟真人猜词。';$('computer').textContent='单机 · 电脑出图';$('local').textContent='单机 · 绘画练习';}

if(game==='draw')render();

if(game==='cards'){$('board').classList.add('cards');$('rules').textContent='颜色数字接龙：两人各7张，轮流打出与桌面同色或同数字的牌，也可摸一张并结束回合。先出完手牌获胜。没有功能牌、不下注；牌库耗尽时重洗弃牌。双人同屏会显示当前玩家手牌，请轮流操作。';render();}

if(game==='pool'){$('board').classList.add('pool');$('rules').textContent='休闲台球：点击球桌瞄准，调整力度后击球。1–7号球是双方共用目标，进球可继续击球；白球落袋则换手并自动复位。清空1–7号后打进8号获胜，提前打进8号或同时白球落袋判负。最多200杆后按落袋数判定。此模式不是完整竞技八球规则。';render();}
